Algorithme PrimitivesChaines;
Var
    ch1, ch2, res : Chaine;
    len : Entier;
Debut
    ch1 := "Algorithmique";
    ch2 := " 2026";

    // 1. Longueur
    len := Longueur(ch1); // 13
    Ecrire("Longueur = ", len);

    // 2. Concaténation
    res := Concat(ch1, ch2); // "Algorithmique 2026"
    Ecrire("Concaténation = ", res);
Fin.

Algorithme TestPalindrome;
Var
    ch : Chaine;
    N, i : Entier;
    estPalindrome : Booleen;
Debut
    Ecrire("Entrez un mot :");
    Lire(ch);
    N := Longueur(ch);

    estPalindrome := Vrai;
    Pour i := 1 a N div 2 Faire
        Si (ch[i] <> ch[N - i + 1]) Alors
            estPalindrome := Faux;
        Fin Si;
    Fin Pour;

    Si estPalindrome Alors
        Ecrire(ch, " est un PALINDROME ! 🎯");
    Sinon
        Ecrire(ch, " n'est pas un palindrome.");
    Fin Si;
Fin.

Algorithme ConversionChaineNombre;
Var
    ch : Chaine;
    N, i, val, chiffre : Entier;
Debut
    ch := "1234";
    N := Longueur(ch);
    val := 0;

    Pour i := 1 a N Faire
        chiffre := Ord(ch[i]) - Ord('0'); // Conversion du caractère en chiffre
        val := val * 10 + chiffre;        // Accumulation décimale
    Fin Pour;

    Ecrire("Valeur entière calculée : ", val);
    Ecrire("Le double de la valeur est : ", val * 2); // Preuve que c'est un entier !
Fin.
